'use strict';

const THEME_KEY='inspired-theme';
function applyTheme(theme,persist=false){
 const chosen=theme==='light'?'light':'dark';
 document.documentElement.dataset.theme=chosen;
 const toggle=document.getElementById('theme-toggle');
 toggle.setAttribute('aria-checked',String(chosen==='dark'));
 toggle.title=chosen==='dark'?'Switch to light theme':'Switch to dark theme';
 document.getElementById('theme-label').textContent=chosen==='dark'?'Dark':'Light';
 document.getElementById('theme-icon').innerHTML=chosen==='dark'?'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.3 15.3A8.5 8.5 0 0 1 8.7 3.7a8.5 8.5 0 1 0 11.6 11.6Z"/></svg>':'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/></svg>';
 document.querySelector('meta[name="theme-color"]').setAttribute('content',chosen==='dark'?'#080807':'#f7f4ec');
 if(persist){try{localStorage.setItem(THEME_KEY,chosen);}catch(e){}}
}
let initialTheme='dark';
try{initialTheme=localStorage.getItem(THEME_KEY)==='light'?'light':'dark';}catch(e){}
applyTheme(initialTheme);
document.getElementById('theme-toggle').addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true));

let portalInstallPrompt=null,portalInstallAccepted=false;
const browserNavigator=typeof navigator==='undefined'?{}:navigator;
function portalIsInstalled(){return portalInstallAccepted||window.matchMedia?.('(display-mode: standalone)').matches||browserNavigator.standalone===true;}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();portalInstallPrompt=event;});
window.addEventListener('appinstalled',()=>{portalInstallAccepted=true;portalInstallPrompt=null;document.querySelector('.install-panel')?.remove();});
if('serviceWorker' in browserNavigator&&location.protocol==='https:')browserNavigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{});
function renderInstallCard(base){
 if(base!=='account'||portalIsInstalled())return;
 document.getElementById('main').insertAdjacentHTML('beforeend',`<section class="panel install-panel"><div class="eyebrow">${icon('phone')}INSPIRED ON YOUR HOME SCREEN</div><h2>One tap to your learning.</h2><p>Add InspirED to your home screen. Open your notes, classes and tests in an app window.</p><button class="button" data-action="install-app">${icon('download')}Install InspirED</button><small>Free website app · Premium courses continue in the APPX app.</small></section>`);
}
async function installPortalApp(){
 if(portalInstallPrompt){const prompt=portalInstallPrompt;portalInstallPrompt=null;try{await prompt.prompt();const result=await prompt.userChoice;if(result?.outcome==='accepted'){portalInstallAccepted=true;document.querySelector('.install-panel')?.remove();}return;}catch(e){}}
 showModal(`<h2>Add InspirED to your home screen</h2><p><strong>Android:</strong> open this website in Chrome, open the three-dot menu, then choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p><p><strong>iPhone or iPad:</strong> open this website in Safari, tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</p><p>If your browser offers an Install option, use it to open InspirED in its own app window.</p><div class="dialog-actions"><button class="button" data-action="close-modal">Got it</button></div>`);
}

